SELECT 
FROM projects





                OR title LIKE '%' || #{keyword} || '%'


                OR skill LIKE '%' || #{keyword} || '%'


                OR commercial_flow LIKE '%' || #{keyword} || '%'


                OR work_location LIKE '%' || #{keyword} || '%'


                OR summary LIKE '%' || #{keyword} || '%'


                OR note LIKE '%' || #{keyword} || '%'




        AND status IN

            #{status}


    AND start_date >= #{startDateFrom}
    AND start_date <= #{startDateTo}
    AND end_date >= #{endDateFrom}
    AND end_date <= #{endDateTo}
    AND created_at::date >= #{registeredDateFrom}
    AND created_at::date <= #{registeredDateTo}

        AND created_by LIKE '%' || #{registrant} || '%'


        AND created_department LIKE '%' || #{registrantDepartment} || '%'


        AND client_name LIKE '%' || #{client} || '%'

    AND bp_recruitment = #{bpRequiredCode}

ORDER BY management_code DESC
